-- drugs
('1f50c', '🔌', 'The "plug": a drug dealer or connection (can also mean a source for sneakers, vapes, etc.)', 'YELLOW', 'Listed by the DEA as an emoji used to advertise drug dealers.', 'Ask casually who "the plug" is and what they get from them. Curiosity first, not accusations.', 'KNOWN', true, true),
('plug', 'plug', 'A dealer or connection who can get something (often drugs or vapes)', 'YELLOW', 'Common slang for a drug dealer.', 'Ask what kind of plug they mean. Often it is harmless, sometimes it is not.', 'KNOWN', true, false),
('2744', '❄️', 'Can be a code for cocaine or meth', 'YELLOW', 'Listed by the DEA as a drug emoji code. Context matters: it is also just snow.', 'If it shows up next to money or 🔌 emojis, ask directly and calmly.', 'KNOWN', true, true),
('1f48a', '💊', 'Pills. Counterfeit pills sold online often contain fentanyl', 'YELLOW', 'The DEA estimates about 4 in 10 counterfeit pills contain a potentially lethal dose of fentanyl.', 'Make sure your kid knows: any pill not from a pharmacy can be fake and deadly.', 'KNOWN', true, true),
('perc', 'perc', 'Percocet. Pills sold as "percs" on social media are usually counterfeit and often contain fentanyl', 'RED', 'Fake "percs" are a leading cause of teen overdose deaths.', 'Say: "I am not mad, I am scared. Pills from friends or online can be fentanyl. Can we talk?"', 'KNOWN', true, true),
('percs', 'percs', 'Percocet pills, very often counterfeit and laced with fentanyl', 'RED', 'Fake "percs" are a leading cause of teen overdose deaths.', 'Say: "I am not mad, I am scared. Pills from friends or online can be fentanyl. Can we talk?"', 'KNOWN', true, true),
('m30', 'M30', 'Counterfeit oxycodone pill ("blues"), very often pressed with fentanyl', 'RED', 'M30 "blues" are the most common fake pill linked to fentanyl deaths.', 'Treat as urgent. Talk today, calmly, and consider calling your pediatrician or SAMHSA (1-800-662-4357).', 'KNOWN', true, true),
('blues', 'blues', 'Counterfeit M30 oxycodone pills, often containing fentanyl', 'RED', 'Street name for fake pills linked to fentanyl deaths.', 'Ask what they mean by "blues". If it is pills, talk today.', 'KNOWN', true, false),
('fent', 'fent', 'Fentanyl', 'RED', 'Fentanyl is involved in most teen overdose deaths.', 'Treat as urgent. Talk today and remove access to any pills you find.', 'KNOWN', true, true),
('xans', 'xans', 'Xanax. Pills sold as Xanax online are often counterfeit and can contain fentanyl', 'RED', 'Counterfeit Xanax ("bars") is a common source of fentanyl exposure.', 'Ask where they heard about it. Explain fake pills can be deadly even once.', 'KNOWN', true, true),
('zannies', 'zannies', 'Xanax pills, often counterfeit', 'RED', 'Counterfeit Xanax can contain fentanyl.', 'Ask where they heard about it. Explain fake pills can be deadly even once.', 'KNOWN', true, true),
('zaza', 'zaza', 'High-quality marijuana', 'YELLOW', 'Common weed slang.', 'Ask what they know about weed and vapes. Share facts, not lectures.', 'KNOWN', true, true),
('1f341', '🍁', 'Marijuana', 'YELLOW', 'Listed by the DEA as a marijuana emoji code.', 'Ask what they know about weed and vapes. Share facts, not lectures.', 'KNOWN', true, true),
('1f343', '🍃', 'Can mean marijuana', 'YELLOW', 'Listed by the DEA as a marijuana emoji code.', 'Look at the context before reacting.', 'KNOWN', true, false),
('carts', 'carts', 'THC vape cartridges', 'YELLOW', 'Unregulated THC carts can be contaminated.', 'Ask if friends vape and what they think about it.', 'KNOWN', true, false),
('molly', 'molly', 'MDMA (ecstasy). Can also just be a name', 'YELLOW', 'Common drug slang, often cut with other substances.', 'Check the context. If it is the drug, talk about what is really in street drugs.', 'KNOWN', true, false),
('lean', 'lean', 'Prescription cough syrup with codeine mixed with soda', 'YELLOW', 'Codeine is an opioid; "lean" is glamorized in music.', 'Ask if anyone at school drinks lean and what they think of it.', 'KNOWN', true, false),
('zooted', 'zooted', 'Very high on drugs', 'YELLOW', 'Describes being intoxicated.', 'Ask who was zooted and how they felt about it.', 'KNOWN', true, true),
-- self-harm, suicide, eating disorders
('kms', 'kms', '"Kill myself". Usually exaggeration ("I failed the test, kms") but not always', 'YELLOW', 'Mostly hyperbole, but repeated use or a serious tone deserves attention.', 'Check in gently: "You said kms. Rough day? I am here." If it sounds serious, call or text 988.', 'KNOWN', true, true),
