('thinspo', 'thinspo', '"Thinspiration": content that glorifies extreme thinness', 'RED', 'A common eating-disorder community term.', 'Do not shame. Say you noticed and want to understand. Talk to your pediatrician.', 'KNOWN', true, true),
('meanspo', 'meanspo', 'Insults people ask for to motivate extreme dieting', 'RED', 'An eating-disorder community term.', 'Do not shame. Say you noticed and want to understand. Talk to your pediatrician.', 'KNOWN', true, true),
('edtwt', 'edtwt', '"Eating disorder Twitter": online eating-disorder communities', 'RED', 'These communities encourage disordered eating.', 'Do not shame. Say you noticed and want to understand. Talk to your pediatrician.', 'KNOWN', true, true),
