('seggs', 'seggs', '"Sex" (algospeak)', 'YELLOW', 'Sexual reference, often joking.', 'Talk about healthy relationships without shaming.', 'KNOWN', true, true),
('1f346', '🍆', 'Sexual reference (penis)', 'YELLOW', 'Common sexual emoji.', 'Look at who sent it. From a stranger or adult, it is a red flag.', 'KNOWN', true, true),
('1f351', '🍑', 'Can mean butt / sexual', 'YELLOW', 'Common sexual emoji. Also just a peach.', 'Look at the context and who sent it.', 'KNOWN', true, false),
